// porticoNonceLen is the fixed length in hex chars of the nonce prefix in the
// OAuth state generated by BuildAuthorizationURL. The remaining suffix carries
// the original routing state of the sign-in flow.
const porticoNonceLen = 32

const (
	porticoSigninStateKeyPrefix = "portico:signin:state:"
	porticoSigninStateTTL       = 10 * time.Minute
	porticoCodeVerifierBytes    = 32
)

// porticoClientImpl talks to a Portico OIDC provider. Portico mandates the
// authorization code flow with PKCE (S256), so sign-in must be initiated by
// the backend: the code verifier never leaves this server, only the derived
// challenge is sent to Portico.
type porticoClientImpl struct {
	endpoint     string
	clientID     string
	clientSecret string
	redirectURI  string
	scopes       []string
	cache        cache.RedisClient
}

func NewPorticoClient(config *config.Config) (SSOInterface, error) {
	rc, err := cache.NewCache(context.Background(), cache.RedisConfig{
		Addr:     config.Redis.Endpoint,
		Username: config.Redis.User,
		Password: config.Redis.Password,
	})
	if err != nil {
		return nil, fmt.Errorf("failed to create cache for portico sso client,error:%w", err)
	}

	return &porticoClientImpl{
		endpoint:     strings.TrimSuffix(config.Portico.Endpoint, "/"),
		clientID:     config.Portico.ClientID,
		clientSecret: config.Portico.ClientSecret,
		redirectURI:  config.Portico.RedirectURI,
		scopes:       strings.Fields(config.Portico.Scopes),
		cache:        rc,
	}, nil
}

var _ SSOInterface = (*porticoClientImpl)(nil)

// BuildAuthorizationURL starts the backend-initiated sign-in flow with PKCE.
// It generates a nonce and code verifier, stores the verifier in Redis keyed
// by the nonce, and returns the Portico authorization URL together with the
// full OAuth state (nonce prefix + routing state). The caller must bind the
// returned state token to the initiating browser and verify it again on the
// callback, otherwise a code redeemed from a different browser would still
// pass PKCE.
func (p *porticoClientImpl) BuildAuthorizationURL(ctx context.Context, routingState string) (string, string, error) {
	nonce, err := generatePorticoNonce()
	if err != nil {
		return "", "", fmt.Errorf("failed to generate portico signin nonce,error:%w", err)
	}
	verifier, err := generatePorticoCodeVerifier()
	if err != nil {
		return "", "", fmt.Errorf("failed to generate portico code verifier,error:%w", err)
	}

	err = p.cache.SetEx(ctx, porticoSigninStateKey(nonce), verifier, porticoSigninStateTTL)
	if err != nil {
		return "", "", fmt.Errorf("failed to persist portico signin state,error:%w", err)
	}

	conf := &oauth2.Config{
		ClientID:     p.clientID,
		ClientSecret: p.clientSecret,
		RedirectURL:  p.redirectURI,
		Scopes:       p.scopes,
		Endpoint: oauth2.Endpoint{
			AuthURL:   p.endpoint + "/authorize",
			TokenURL:  p.endpoint + "/oauth/token",
			AuthStyle: oauth2.AuthStyleInHeader,
		},
	}
	oauthState := nonce + routingState
	authCodeURL := conf.AuthCodeURL(oauthState,
		oauth2.SetAuthURLParam("code_challenge", computePorticoCodeChallenge(verifier)),
		oauth2.SetAuthURLParam("code_challenge_method", "S256"),
	)

	return authCodeURL, oauthState, nil
}

// GetOAuthToken exchanges the authorization code for an access token. The code
// verifier bound to the state nonce via PKCE is deleted from Redis on use, so
// each sign-in state can only be redeemed once.
func (p *porticoClientImpl) GetOAuthToken(ctx context.Context, code, state string) (*oauth2.Token, error) {
	nonce, _, ok := SplitPorticoSigninState(state)
	if !ok {
		return nil, fmt.Errorf("invalid portico signin state: %s", state)
	}
	verifier, err := p.cache.GetDel(ctx, porticoSigninStateKey(nonce))
	if errors.Is(err, redis.Nil) {
		return nil, fmt.Errorf("portico signin state is invalid or expired")
	}
	if err != nil {
		return nil, errorx.RemoteSvcFail(err,
			errorx.Ctx().Set("service", "portico").
				Set("state", state),
		)
	}

	conf := &oauth2.Config{
		ClientID:     p.clientID,
		ClientSecret: p.clientSecret,
		RedirectURL:  p.redirectURI,
		Endpoint: oauth2.Endpoint{
			AuthURL:   p.endpoint + "/authorize",
			TokenURL:  p.endpoint + "/oauth/token",
			AuthStyle: oauth2.AuthStyleInHeader,
		},
	}
	token, err := conf.Exchange(ctx, code, oauth2.SetAuthURLParam("code_verifier", verifier))
	if err != nil {
		slog.Error("GetOAuthToken failed from portico", slog.Any("error", err))
		return nil, errorx.RemoteSvcFail(err,
			errorx.Ctx().Set("service", "portico").
				Set("code", code),
		)
	}

	return token, nil
}

// GetUserInfo fetches the OIDC userinfo claims for the given access token and
// maps them to the local SSO user info.
func (p *porticoClientImpl) GetUserInfo(ctx context.Context, accessToken string) (*SSOUserInfo, error) {
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, p.endpoint+"/userinfo", nil)
	if err != nil {
		return nil, fmt.Errorf("failed to create portico userinfo request,error:%w", err)
	}
	req.Header.Set("Authorization", fmt.Sprintf("Bearer %s", accessToken))

	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		slog.Error("GetUserInfo failed from portico", slog.Any("error", err))
		return nil, errorx.RemoteSvcFail(err,
			errorx.Ctx().Set("service", "portico").
				Set("access_token", accessToken),
		)
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		body, err := io.ReadAll(resp.Body)
		if err != nil {
			return nil, err
		}
		slog.Error("GetUserInfo failed from portico", slog.Any("status_code", resp.StatusCode), slog.Any("body", string(body)))
		return nil, errorx.RemoteSvcFail(fmt.Errorf("unexpected status code %d from portico userinfo", resp.StatusCode),
			errorx.Ctx().Set("service", "portico").
				Set("access_token", accessToken),
		)
	}

	body, err := io.ReadAll(resp.Body)
	if err != nil {
		return nil, err
	}

	var user struct {
		Sub               string `json:"sub"`
		Name              string `json:"name"`
		PreferredUsername string `json:"preferred_username"`
		Email             string `json:"email"`
		PhoneNumber       string `json:"phone_number"`
	}
	if err := json.Unmarshal(body, &user); err != nil {
		return nil, fmt.Errorf("failed to unmarshal portico userinfo,error:%w", err)
	}

	userName := user.PreferredUsername
	if userName == "" {
		userName = user.Name
	}

	return &SSOUserInfo{
		Name:        userName,
		Email:       user.Email,
		UUID:        user.Sub,
		RegProvider: SSOTypePortico,
		Phone:       user.PhoneNumber,
	}, nil
}

// SplitPorticoSigninState splits the OAuth state generated by
// BuildAuthorizationURL into the nonce prefix and the original routing state.
func SplitPorticoSigninState(state string) (nonce, routingState string, ok bool) {
	if len(state) < porticoNonceLen {
		return "", "", false
	}
	return state[:porticoNonceLen], state[porticoNonceLen:], true
}

func porticoSigninStateKey(nonce string) string {
	return porticoSigninStateKeyPrefix + nonce
}

func generatePorticoNonce() (string, error) {
	b := make([]byte, porticoNonceLen/2)
	if _, err := io.ReadFull(rand.Reader, b); err != nil {
		return "", err
	}
	return hex.EncodeToString(b), nil
}

func generatePorticoCodeVerifier() (string, error) {
	b := make([]byte, porticoCodeVerifierBytes)
	if _, err := io.ReadFull(rand.Reader, b); err != nil {
		return "", err
	}
	return base64.RawURLEncoding.EncodeToString(b), nil
}

func computePorticoCodeChallenge(verifier string) string {
	h := sha256.Sum256([]byte(verifier))
	return base64.RawURLEncoding.EncodeToString(h[:])
}

